from solution import move_one_ball
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(arr):
    """Obviously-correct model: True iff some right-shift yields sorted order."""
    if len(arr) == 0:
        return True
    s = sorted(arr)
    n = len(arr)
    if arr == s:
        return True
    for k in range(1, n):
        # right shift by k
        if arr[-k:] + arr[:-k] == s:
            return True
    return False


def right_rotate(arr, k):
    n = len(arr)
    if n == 0:
        return []
    k = k % n
    if k == 0:
        return list(arr)
    return list(arr[-k:] + arr[:-k])


# ---- concrete examples from spec ----

def test_example_sorted_by_two_shifts():
    assert move_one_ball([3, 4, 5, 1, 2]) is True


def test_example_impossible():
    assert move_one_ball([3, 5, 4, 1, 2]) is False


def test_empty_returns_true():
    assert move_one_ball([]) is True


def test_single_element_returns_true():
    assert move_one_ball([1]) is True
    assert move_one_ball([-5]) is True


def test_two_element_sorted_returns_true():
    assert move_one_ball([1, 2]) is True


def test_two_element_unsorted_returns_true():
    # [2, 1] right-shifted once -> [1, 2]
    assert move_one_ball([2, 1]) is True


def test_right_rotation_by_one_of_sorted_returns_true():
    # Requires detecting the rotation that the buggy range(2, n) misses (i==1)
    assert move_one_ball([5, 1, 2, 3, 4]) is True


def test_three_element_rotation_needing_first_split():
    assert move_one_ball([3, 1, 2]) is True


def test_sorted_array_returns_true():
    assert move_one_ball([1, 2, 3, 4, 5]) is True
    assert move_one_ball([-3, -1, 0, 2]) is True


def test_reverse_sorted_returns_false():
    assert move_one_ball([5, 4, 3, 2, 1]) is False
    assert move_one_ball([3, 2, 1]) is False


# ---- property-based tests ----

@given(st.lists(st.integers(min_value=-20, max_value=20), min_size=0, max_size=8, unique=True))
def test_property_agrees_with_reference_model(arr):
    assert move_one_ball(list(arr)) == reference(list(arr))


@given(st.lists(st.integers(min_value=-50, max_value=50), min_size=1, max_size=8, unique=True),
       st.integers(min_value=0, max_value=20))
def test_property_every_right_rotation_of_sorted_is_true(sorted_unique, k):
    s = sorted(sorted_unique)
    rotated = right_rotate(s, k)
    assert move_one_ball(rotated) is True


@given(st.lists(st.integers(min_value=-20, max_value=20), min_size=0, max_size=8, unique=True))
def test_property_sorted_input_implies_true(arr):
    s = sorted(arr)
    assert move_one_ball(s) is True


@given(st.lists(st.integers(min_value=-20, max_value=20), min_size=2, max_size=7, unique=True))
def test_property_single_right_shift_closure(arr):
    # If arr is rotatable-to-sorted, then shifting it once keeps it rotatable.
    # If arr is not rotatable, shifting it once keeps it non-rotatable.
    assume(move_one_ball(list(arr)) == reference(list(arr)))
    expected = reference(list(arr))
    shifted = right_rotate(arr, 1)
    assert move_one_ball(shifted) == expected


@given(st.lists(st.integers(min_value=-20, max_value=20), min_size=0, max_size=8, unique=True))
def test_property_returns_bool(arr):
    result = move_one_ball(list(arr))
    assert result is True or result is False
